import React, { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import { Card, Typography, Button, Grid } from '@mui/material';
import { useNavigate } from 'react-router-dom';

const Dashboard = () => {
  const { user } = useAuth();
  const [balance, setBalance] = useState(null);
  const [history, setHistory] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    if (user?.token) {
      api.leaveBalance(user.token).then(setBalance);
      api.leaveHistory(user.token).then(setHistory);
    }
  }, [user]);

  return (
    <div>
      <Typography variant="h4" sx={{ mb: 3 }}>Welcome, {user?.username}</Typography>
      <Typography variant="subtitle2" sx={{ mb: 2 }}>Role: {user?.role}</Typography>
      <Grid container spacing={2}>
        <Grid item xs={12} md={6}>
          <Card sx={{ p: 2, mb: 2 }}>
            <Typography variant="h6">Leave Balance</Typography>
            {balance ? (
              Array.isArray(balance) ? (
                <ul>
                  {balance.map(bal => (
                    <li key={bal.id}><b>{bal.leaveType}</b>: {bal.balance}</li>
                  ))}
                </ul>
              ) : (
                <ul>
                  {Object.entries(balance || {}).map(([type, count]) => (
                    <li key={type}><b>{type}</b>: {count}</li>
                  ))}
                </ul>
              )
            ) : (
              <Typography>Loading...</Typography>
            )}
          </Card>
          <Button variant="contained" color="primary" onClick={() => navigate('/leave-requests')}>Apply for Leave</Button>
        </Grid>
        <Grid item xs={12} md={6}>
          <Card sx={{ p: 2 }}>
            <Typography variant="h6">Leave History</Typography>
            {history.length > 0 ? (
              <ul>
                {history.map(lh => (
                  <li key={lh.id} style={{ marginBottom: 8 }}>
                    <b>{lh.leaveType}</b> | <b>{lh.status}</b> | {lh.fromDate} to {lh.toDate}
                  </li>
                ))}
              </ul>
            ) : (
              <Typography>No history found.</Typography>
            )}
          </Card>
        </Grid>
      </Grid>
      {/* Optionally add chart/summary etc. */}
    </div>
  );
};
export default Dashboard;
